Vector3f UniformSampleSphere(const Point2f &u) {
    Float z = 1.0f - 2.0f * u[0];
    Float r = std::sqrt(std::max(0.0f, 1.0f - z * z));
    Float phi = 2.0f * M_PI * u[1];
    return Vector3f(r * std::cos(phi), r * std::sin(phi), z);
}

